"""Create six external replication reports from frozen, aggregate experiment outputs."""
import argparse,datetime,hashlib,json,platform
from pathlib import Path
import numpy as np
import pandas as pd
from replicate import latest,NAMES
def table(df):return df.to_markdown(index=False,floatfmt='.6f')
def main():
    ap=argparse.ArgumentParser();ap.add_argument('--results',required=True);ap.add_argument('--predictions',required=True);ap.add_argument('--panels',required=True);ap.add_argument('--lock',required=True);ap.add_argument('--out',required=True);a=ap.parse_args();r=Path(a.results);out=Path(a.out);out.mkdir(parents=True,exist_ok=True);lock=json.loads(Path(a.lock).read_text());logs=[json.loads(s) for s in (r/'confirmation_access.jsonl').read_text().splitlines()];assert [s['hypothesis'] for s in logs if s['status']=='completed']==['H1','H2','H3','H4','H5','H6']
    d=latest(pd.read_csv(Path(a.predictions)/'confirmation_predictions.csv.gz'));control=d[d[['y1','y2','y3']].notna().all(axis=1)];metrics=[]
    for h in (1,2,3):
        z=d[d[f'y{h}'].notna()];p=z[[f'p_{m}_{h}' for m in NAMES]].to_numpy();y=z[f'y{h}'].to_numpy();ls=((p-y[:,None])**2).mean(0)
        for k,m in enumerate(NAMES):metrics.append(dict(horizon=h,n=len(z),model=m,brier=ls[k]))
    pd.DataFrame(metrics).to_csv(r/'model_brier.csv',index=False)
    shared=f'''Данные: NLSY97, public-use архив 1997–2023. Независимые от RLMS люди; опубликованная реконструированная гражданская занятость на неделях NLS, а не проверенная доопросом истинная биография. Freelance не включён в EMP_STATUS провайдером. Коды 2/4/5→0, employer UID>=9701 и <1000000→1; 0/1/3/6, отрицательные и неожиданные промежуточные коды остаются неизвестными.

Разделение по людям зафиксировано до персонального анализа: 5392 train, 1787 development, 1805 confirmation. Общая трёхгоризонтная схема использует 47092 обучающих окна 5253 человек, 1369 development-окон и 2779 подтверждающих окон 1506 человек. Для контролируемых запросов берётся одно последнее окно человека; полностью известных трёхточечных траекторий в этой последней когорте {len(control)}. Неизвестность естественных ответов сохраняется отдельно. Возраст определяется по месяцу и году рождения; точный день рождения не известен. Предусмотренное провайдером восстановление/импутация дат не превращается в независимую проверку истинной биографии.

Интервью задаёт начало: origin — первое воскресенье после конца месяца интервью; признак занятости относится к неделе, завершившейся до начала месяца интервью. Горизонты 52/104/156 недель по официальному crosswalk; календарные блоки определяются по КОНЦУ целевой недели. Train outcomes<=2013, development 2014–2017, confirmation 2018–2023. Все три будущих контроля общего окна должны лежать внутри своего блока. В официальном crosswalk обнаружен шаг 8 дней 2024-09-02; этот период не используется, весь использованный диапазон проверен на шаг 7 дней.

Модели обучены заново только на NLSY97 train: baseline по lagged employment, logistic, HGB. Параметры фиксированы по RLMS до подтверждения; признаки age, sex, lagged employment (историческое имя колонки current_employment). Education исключено из прогнозных признаков из-за edited-значений и отсутствия полной истории релизов, но используется как архивный групповой признак. Это не утверждение о точном историческом vintage всех признаков. Основные веса равны 1/N конечной когорты, а внутри групп нормируются отдельно; обследовательские веса не использованы и национальная репрезентативность не заявляется.

Все основные настройки и расчётный код зафиксированы локально {lock['created_utc']}, до первых confirmation-метрик; SHA256 конфигурации `{lock['experiment_config_sha256']}`. Это локальный журналируемый held-out эксперимент, а не регистрация на внешнем preregistration-сервисе. После открытия confirmation модели и политики не перенастраивались. Порядок открытия H1→H6 сохранён в confirmation_access.jsonl. Последовательные гипотезы используют одну заранее оговорённую панель; это не шесть независимых новых выборок. Вероятностные уровни C3 относятся к описанной семье конкретного эксперимента; общего 95%-покрытия всех шести гипотез одним статистическим утверждением не заявляется. Детерминированный C1 такой поправки не требует.
'''
    (out/'methodology.md').write_text('# Общая методика внешней проверки NLSY97\n\n'+shared+'\n\n'+table(pd.DataFrame(metrics)))
    h1=pd.read_csv(r/'H1_runs.csv');summary=pd.read_csv(r/'H1_summary.csv');main=summary[(summary.mechanism=='MCAR')&(summary.missing_fraction==.2)];assert not h1.wrong_certificate.any()
    text=f'''# H1 — достаточный выбор при скрытых ответах: NLSY97

Внешняя основная проверка выполнена. C1 может сертифицировать выбор при неизвестных ответах, но частота зависит от горизонта, пропусков и различий моделей. Это не доказательство универсального успеха.

Протокол: 3 горизонта × MCAR/MAR/MNAR × 10/20/40% скрытия × 100 масок. C0/C1 работают на исходной информации; C1_same_audit и uniform_C3 получают одни и те же до 50 дополнительно проверенных меток. Цена аудита записана отдельно. C3 использует поправку на пары моделей и всю предусмотренную семью масок/горизонтов/механизмов; выборка аудита равномерна без возвращения среди скрытых строк, label-iid не предполагается.

Основной пример с 20% MCAR:

{table(main)}

У двухлетнего горизонта C1 прошёл в 52% масок, а после 50 проверок — в 96%. На горизонтах 1 и 3 без аудита при 20% MCAR сертификатов нет. Разница между горизонтами относится к возможности выбрать среди кандидатов, а не к утверждению, что более дальний прогноз точнее. C0 не выдал сертификатов в этом основном режиме.

C3 здесь имеет ту же частоту сертификатов, что C1 на тех же раскрытых метках; улучшение относительно C1 без аудита нельзя приписывать статистической формуле. Ложных сертификатов {int(h1.wrong_certificate.sum())} из {int(h1.certified.sum())} выданных контрольных точек; эти точки не являются независимыми новыми выборками людей.

Scope: основная внешняя проверка C0/C1/C3. C2 проверяется отдельно как условная Gamma-чувствительность H3. Итог: полезность C1 получила ограниченную эмпирическую поддержку, не универсальную гарантию узости интервалов.
''';(out/'H1_NLSY97.md').write_text(text)
    h2=pd.read_csv(r/'H2_runs.csv');h2sum=pd.read_csv(r/'H2_summary.csv');pair=h2.pivot(index='rep',columns='policy',values='cost');saving=1-pair.Q2.mean()/pair.random.mean();delta=pair.random-pair.Q2;pd.DataFrame([dict(comparator='Q2 vs random',paired_masks=len(pair),mean_saved=float(delta.mean()),fraction_masks_better=float((delta>0).mean()),min_saved=int(delta.min()),max_saved=int(delta.max()),relative_mean_saving=float(saving))]).to_csv(r/'H2_paired_comparison.csv',index=False)
    text=f'''# H2 — стоимость активной проверки: NLSY97

Основной внешний эксперимент выполнен: одно последнее полное окно каждого человека, endpoint через 156 недель, 20% искусственно скрытых ответов, 100 одинаковых для всех политик масок, цена запроса 1, предел 200. Каждый метод останавливается по тому же C1 и epsilon=0.0025. В выборе очередного запроса скрытые ответы недоступны.

{table(h2sum)}

Предварительно выбранный на RLMS для единичной цены Q2 потребовал в среднем {pair.Q2.mean():.2f} проверки против {pair.random.mean():.2f} у random: экономия {100*saving:.1f}%. Во всех 100 парных масках цена Q2 была ниже random (разница от {int(delta.min())} до {int(delta.max())} запросов); сертификаты получили все методы. Q0/Q1/Q2 совпали по результатам. Это сравнение стоимости одного и того же решения на конечной когорте, а не только рейтинга при разных бюджетах.

Hara_adapter и ActiveTesting_adapter используют идеи соответствующих query distributions с общим C1; оригинальные paper-estimators/LURE здесь не воспроизведены. После основного H1–H6 выполнено отдельное [расширение CODA](../extensions/coda/report/H2_CODA_extension.md): CODA_bridge — 76,05, CODA_conditioned с известными ответами — 76,80 запроса против 66,15 у Q2; при бюджете 200 все дали 100/100 сертификатов, Q2 дешевле на каждой маске. Это адаптация авторской EIG-очередности к Brier+C1 на уже использованной когорте, а не новый независимый тест или полное воспроизведение экспериментов статьи.
''';(out/'H2_NLSY97.md').write_text(text)
    h3sum=pd.read_csv(r/'H3_summary.csv');gamma=pd.read_csv(r/'H3_Gamma_sensitivity.csv');gammatable=gamma.groupby('Gamma').agg(runs=('rep','count'),premise_rate=('premise_holds','mean'),certificate_rate=('certified','mean'),wrong=('wrong_certificate_unconditional','sum')).reset_index();natural=json.loads((r/'H3_natural_bounds.json').read_text())
    text=f'''# H3 — неответы и условные ограничения: NLSY97

Выполнены 50 масок для MCAR/MAR/MNAR неответов и четырёх политик; начально скрыты 20% известных endpoint-меток. Одна попытка стоит 1 даже при отказе. Неудачная попытка остаётся неизвестной и повторно не запрашивается. Ответная модель обучена по X и синтетическим response-indicators только development; истинный скрытый y используется лишь oracle для генерации MNAR и последующей оценки. Ошибочная модель меняет p_response на clip(1-p_response,.05,.95).

{table(h3sum)}

Все методы получили C1-сертификат в этих контролируемых сериях. Однако response-aware улучшение не универсально: в MAR цены Q1 и response-weighted совпали, в MNAR различие небольшое, а ошибочная response-модель увеличила цену. Обоснованность C1 не требует верной response-модели.

Gamma-чувствительность отдельно ограничивает odds скрытой доли единиц относительно видимой, с целочисленной внешней оболочкой floor/ceil; это предположение, а не установленный факт:

{table(gammatable)}

На выбранном сильном MNAR все Gamma-предпосылки нарушены. Даже ноль наблюдаемых ошибок выбора не подтверждает корректность этих предпосылок; условные Gamma-сертификаты не публикуются как безусловная гарантия.

Естественная неполнота: {natural['unknown']} неизвестных endpoint из {natural['n']}, C1 G={natural['G']:.6f}; при основном epsilon=0.0025 отказ. Эти случаи включают неоднозначность статуса и отсутствие последующего наблюдения, а не только отказ отвечать. Истинный regret на них не вычисляется, поскольку истинные ответы отсутствуют.
''';(out/'H3_NLSY97.md').write_text(text)
    info=pd.read_csv(r/'H4_P0_P1.csv');prices=pd.read_csv(r/'H4_P2_summary.csv');it=info.groupby(['target','mode']).agg(masks=('rep','count'),mean_G=('G','mean'),certificate_rate=('certified','mean')).reset_index()
    text=f'''# H4 — частичные траектории и блоковые запросы: NLSY97

Проверены 100 человек, выбранных стабильным хешем до масок, с известными тремя контрольными исходами и lagged employment=1. 20 масок скрывают по 20% точек. Targets: endpoint, средний Brier трёх горизонтов и первое наблюдаемое отсутствие работы на трёх будущих контрольных точках. Это не истинная дата первого ухода из работы между неделями/интервью.

P1 перебирает допустимые бинарные траектории; P0 для first-exit допускает независимые exit-маргиналы, сохраняя все уже установленные по известным состояниям факты. На полностью известных путях обе процедуры точны. Сравнение информации:

{table(it)}

В этом наборе кандидатов дополнительного уменьшения G от P1 не обнаружено, включая first-exit. Общая теория допустимых путей корректна, но практическая выгода не обязательна.

Сравнение P2 при бюджете 20:

{table(prices)}

При цене блока 0.5 подтверждены 90% масок, при point-only — 5%; при цене блока 1.5 block-only не подтверждает ни одной. Это сравнение достижимости при фиксированном бюджете. Средняя потраченная цена включает отказы, поэтому её нельзя объявлять средней ценой успешного решения или вычислять по ней универсальную экономию. Цена блока является сценарным параметром, а не измеренной ценой реального доопроса.

Выбор и точки, и блока использует minimax по возможным ответам; при равенстве — публичное уменьшение ширины/цены и стабильные индексы. Скрытый истинный ответ применяется только после выбора действия. Старый RLMS P2 использовал oracle point-gain; ошибка исправлена и RLMS пересчитан. Старые ценовые числа отозваны. Подробности и ссылка на исправленный RLMS-отчёт — в H4_RLMS_audit.md; прямое сравнение расходов требует учитывать различия когорт и бюджетов.
''';(out/'H4_NLSY97.md').write_text(text)
    h5sum=pd.read_csv(r/'H5_summary.csv');groups=pd.read_csv(r/'H5_full_information.csv');worst=groups.sort_values('true_regret',ascending=False).groupby('model',sort=False).head(1);worst.to_csv(r/'H5_oracle_worst_groups.csv',index=False)
    decisions=pd.read_csv(r/'H5_G0_G1_G2.csv');examples=decisions[(decisions.method=='G0')&decisions.certified&(decisions.true_max_group_regret>.005)];examples.head(12).to_csv(r/'H5_global_certificate_group_failure_examples.csv',index=False)
    text=f'''# H5 — групповые требования: NLSY97

Заранее заданы возрастные группы 18–29, 30–34, 35–39, 40–44; пол; наличие bachelor/выше (degree=4..7), остальные валидные degree=0..3, и неизвестное образование отдельно. В confirmation группа 18–29 не представлена — для неё не заявляется свидетельство качества. Непустые малые группы остаются ограничениями. Все три горизонта и непустые группы проверяются совместно, epsilon_group=0.005.

{table(groups[['group','n','small_group']].drop_duplicates())}

Проверены G0/G1/G2 и три стратегии; 30 масок × uniform/skew/MAR/MNAR. Максимальный бюджет 2000, один оплаченный запрос раскрывает один человеко-горизонтный исход и обновляет все пересекающиеся группы. Ответы заранее не используются при выборе. Результаты:

{table(h5sum)}

Здесь есть реальный пример, ради которого нужна H5: общий G0-сертификат проходит, а групповое отставание превышает 0.005. Это произошло в {len(examples)} сохранённых финальных контрольных точках; они повторяют те же фиксированные истинные группы, а не являются независимыми выборками людей. Для HGB максимальный групповой regret около 0.0443, хотя общий выбор сертифицирован. Нельзя выдавать глобальную гарантию за групповую. Примеры записаны в H5_global_certificate_group_failure_examples.csv без индивидуальных данных.

Подходящей одной модели среди трёх нет даже при всех известных ответах. Максимальный истинный групповой regret каждого кандидата:

{table(worst[['model','group','horizon','n','true_regret']])}

Особенно ограничивает выбор группа неизвестного образования из 7 человек. Это конечногрупповой результат с высокой чувствительностью к малому N, а не доказательство дискриминации или популяционного вреда. Допуск и группы после просмотра результатов не изменялись.

При гарантированных ответах все исходные пропуски раскрываются, но групповой сертификат невозможен для данного набора кандидатов. При MAR/MNAR сама процедура может иметь недостаток информации, тогда как внешний oracle-оценщик дополнительно знает, что требование невыполнимо. Результат не подтверждает перенос RLMS-экономии H5 на эту NLSY97-когорту. Он подтверждает практический смысл отказа: новые labels не исправляют отсутствие подходящего кандидата. Расширение моделей или смена групп после этого потребует нового development-протокола, а не переобъявления этого test успешным.
''';(out/'H5_NLSY97.md').write_text(text)
    t01=pd.read_csv(r/'H6/T0_T1.csv');t4=pd.read_csv(r/'H6/T4_summary.csv');t2=pd.read_csv(r/'H6/T2_weight_scenarios.csv');ver=json.loads((r/'H6/verification.json').read_text());t4runs=pd.read_csv(r/'H6/T4_runs.csv')
    text=f'''# H6 — перенос между периодами: NLSY97

Использованы те же замороженные NLSY97-модели горизонта 52 недели, обученные на раннем train. Календарные пары зафиксированы до confirmation, оценки только по известным бинарным исходам. В каждой годовой когорте одна последняя запись человека; общие люди в разные годы допустимы, OOF доменного классификатора разбит по людям.

{table(t01)}

HGB сохранил первое место, T1 не улучшил выбор. При 2015→2019 ESS весов составляет лишь 26.3%, domain AUC≈0.985: состав сильно различается. Эвристический порог weak_overlap=25% формально не сработал, но это не доказывает наличие хорошего overlap или неизменность P(y|x). Никакой будущий сертификат T0/T1 не выдаёт.

T2 на полностью известных старых записях:

{table(t2[t2.missing_fraction==0])}

Все сравнения выдерживают диапазон весов ±25%; ±50% — только старую когорту 2021; при ±100% сертификаты не проходят. Это ограничения на веса тех же записей, не доказательство фактической границы экономического сдвига.

T3 публикуется только как чувствительность к неизвестному совместному TV(X,Y), rho=0/.01/.03/.1. Переход +2rho проверен на известных синтетических распределениях; iid-поправка используется только на iid-синтетике. Реальный joint rho не установлен ни по X, ни по domain AUC.

T4, 200 попыток, гарантированный ответ:

{table(t4[(t4.budget==200)&(t4.scenario=='complete_response')])}

Всего {len(t4runs)} контрольных точек на всех бюджетах и сценариях; сертификатов {int(t4runs.certified.sum())}. Это результат именно проверенных малых бюджетов и строгого epsilon; он не доказывает невозможность проверки при большем бюджете. Рекомендация при отказе не является выбранной гарантированно хорошей моделью и может проигрывать T0 по фактическому regret.

Uniform+C3 выбирает попытки без возвращения; у неответивших выбранных строк разности потерь ограничиваются по обоим y, а не исключаются. Поправка охватывает 3 когорты × 3 сценария × 100 повторов, 4 бюджета и 6 пар. Iid панельных строк не предполагается. Наблюдаемых нарушений покрытия {ver['C3_coverage_failure_checkpoints']}.

Сохранены проверки 100 LP, монотонности, C1, векторизованного Q2 и независимости политики от скрытых labels. Контрпример одинаковых X и изменившегося P(y|x) даёт future regret=0.64; положительный контроль с известными covariate weights снижает regret с 0.512 до 0. Это контролируемые математические примеры, а не реальные обнаруженные сдвиги ответов NLSY97.
''';(out/'H6_NLSY97.md').write_text(text)
    summary='''# NLSY97 — итог основной внешней проверки H1–H6

Подготовка и последовательный зафиксированный confirmation-run выполнены. Это основная внешняя репликация, а не полное повторение всех вариантов/авторских baseline-реализаций первоначального большого плана.

| Гипотеза | Итог |
|---|---|
| H1 | C1 иногда подтверждает выбор при скрытых ответах; частота существенно зависит от режима. C3 не улучшает C1 на тех же 50 ответах в основном сравнении |
| H2 | Q2: 66.15 проверки против 78.42 random, около 15.6% меньше, оба 100/100 сертификатов |
| H3 | C1 сохраняет обоснованность и при контролируемых неответах; response-aware эффект условный; Gamma-предпосылки в сильном MNAR нарушены |
| H4 | Дополнительной выгоды P1 не найдено; дешёвые блоки повышают достижимость сертификата при фиксированном бюджете, дорогие — нет |
| H5 | Для всех непустых групп нет подходящего общего кандидата даже при известных ответах; RLMS-экономия не воспроизвелась |
| H6 | Прежний HGB сохранил первое место, T1 не улучшил выбор; малой проверки новой когорты недостаточно для строгого сертификата |

Главные границы: сравнительно узкая возрастная когорта; реконструированная опубликованная разметка; маленькие группы; естественные неизвестные ответы не имеют oracle. Нельзя писать «все шесть гипотез положительно доказаны».

Полное воспроизведение оригинальных paper-estimators/LURE и исходных экспериментов статьи CODA, месячная/недельная H4-сетка как отдельная гипотеза и независимый UKHLS/PSID benchmark остаются расширениями. Исправление oracle point-gain и пересчёт RLMS-H4 P2 завершены отдельно; см. H4_RLMS_audit.md. Эти пункты не скрываются статусом выполненного основного NLSY97-run. Отдельное сравнение CODA с общим C1 выполнено: [отчёт расширения](../extensions/coda/report/H2_CODA_extension.md), 76,80 запроса у CODA_conditioned против 66,15 у Q2 при 100/100 сертификатах.
''';(out/'replication_summary.md').write_text(summary)
